.sl-feature-panels {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3rem, 6vw, 5.5rem);
}
.sl-feature-panels h2,
.sl-feature-panels h3 {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-feature-panels .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-feature-panels .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-feature-panels .sl-border { border-color: var(--smartlearn-card-border); }
.sl-feature-panels .sl-panels-subtitle { max-width: 600px; }
.sl-feature-panels .sl-media-fallback {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text-muted);
}
.sl-feature-panels .sl-panels-container {
    padding: 0.5rem;
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
}
.sl-feature-panels .sl-panel {
    border-radius: var(--smartlearn-radius, 0.75rem);
    transition: flex 0.5s cubic-bezier(0.25, 1, 0.5, 1), border-color 0.3s ease;
    border: 2px solid transparent;
}
.sl-feature-panels .sl-panel-hitarea {
    position: absolute;
    inset: 0;
    z-index: 2;
    background: transparent;
    border: 0;
    padding: 0;
    cursor: pointer;
}
.sl-feature-panels .sl-panel-hitarea:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: -3px;
    border-radius: var(--smartlearn-radius, 0.75rem);
}
.sl-feature-panels .sl-panel-content {
    pointer-events: none;
}
.sl-feature-panels .sl-panel-content [data-sl-edit] {
    pointer-events: auto;
}
.sl-feature-panels .sl-panel-title {
    color: #fff;
}
.sl-feature-panels .sl-panel-desc {
    color: rgba(255, 255, 255, 0.92);
}
@media (min-width: 992px) {
    .sl-feature-panels .sl-panels-container { height: 500px; }
    .sl-feature-panels .sl-panel { flex: 1; height: 100%; min-width: 110px; }
    .sl-feature-panels .sl-panel.active { flex: 5; border-color: var(--smartlearn-primary); }
    @media (hover: hover) {
        .sl-feature-panels .sl-panels-container:has(.sl-panel:hover) .sl-panel:not(:hover) {
            flex: 1;
            border-color: transparent;
        }
        .sl-feature-panels .sl-panels-container .sl-panel:hover {
            flex: 5;
            border-color: var(--smartlearn-primary);
        }
    }
}
@media (max-width: 991.98px) {
    .sl-feature-panels .sl-panel { flex: 0 0 80px; min-height: 80px; }
    .sl-feature-panels .sl-panel.active { flex: 1 1 300px; min-height: 300px; border-color: var(--smartlearn-primary); }
}
.sl-feature-panels .sl-panel-bg {
    filter: grayscale(80%);
    transition: filter 0.5s ease, transform 0.5s ease;
}
.sl-feature-panels .sl-panel.active .sl-panel-bg {
    filter: grayscale(0%);
    transform: scale(1.05);
}
@media (hover: hover) {
    .sl-feature-panels .sl-panel:hover .sl-panel-bg {
        filter: grayscale(0%);
        transform: scale(1.05);
    }
}
.sl-feature-panels .sl-panel-overlay {
    background: linear-gradient(to top, rgba(0, 0, 0, 0.9) 0%, rgba(0, 0, 0, 0.35) 55%, rgba(0, 0, 0, 0.05) 100%);
}
.sl-feature-panels .sl-panel-details {
    display: grid;
    grid-template-rows: 0fr;
    opacity: 0;
    transition: grid-template-rows 0.4s ease, opacity 0.3s ease, margin-top 0.3s ease;
}
.sl-feature-panels .sl-panel-details-inner {
    overflow: hidden;
}
.sl-feature-panels .sl-panel.active .sl-panel-details {
    grid-template-rows: 1fr;
    opacity: 1;
    margin-top: 0.75rem;
}
@media (hover: hover) {
    .sl-feature-panels .sl-panel:hover .sl-panel-details {
        grid-template-rows: 1fr;
        opacity: 1;
        margin-top: 0.75rem;
    }
    .sl-feature-panels .sl-panels-container:has(.sl-panel:hover) .sl-panel:not(:hover) .sl-panel-details {
        grid-template-rows: 0fr;
        opacity: 0;
        margin-top: 0;
    }
}
.sl-feature-panels .sl-panel-icon {
    width: 40px;
    height: 40px;
    min-width: 40px;
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text);
    transition: background-color 0.3s ease, color 0.3s ease;
}
.sl-feature-panels .sl-panel.active .sl-panel-icon {
    background-color: var(--smartlearn-primary);
    color: var(--smartlearn-btn-text);
}
@media (hover: hover) {
    .sl-feature-panels .sl-panel:hover .sl-panel-icon {
        background-color: var(--smartlearn-primary);
        color: var(--smartlearn-btn-text);
    }
    .sl-feature-panels .sl-panels-container:has(.sl-panel:hover) .sl-panel:not(:hover) .sl-panel-icon {
        background-color: var(--smartlearn-card-bg);
        color: var(--smartlearn-text);
    }
}
@media (prefers-reduced-motion: reduce) {
    .sl-feature-panels .sl-panel,
    .sl-feature-panels .sl-panel-bg,
    .sl-feature-panels .sl-panel-details,
    .sl-feature-panels .sl-panel-icon {
        transition: none;
    }
    .sl-feature-panels .sl-panel.active .sl-panel-bg,
    .sl-feature-panels .sl-panel:hover .sl-panel-bg {
        transform: none;
    }
}

