(function() {
    function initPanels(root) {
        if (root.dataset.slInit === '1') return;
        root.dataset.slInit = '1';

        const panels = Array.from(root.querySelectorAll('.sl-panel'));
        const triggers = panels.map(p => p.querySelector('.sl-panel-hitarea'));
        if (!panels.length) return;

        const uid = 'sl-panels-' + Math.random().toString(36).slice(2, 8);
        panels.forEach((panel, idx) => {
            const content = panel.querySelector('.sl-panel-details');
            const trigger = triggers[idx];
            if (content && trigger) {
                const cid = uid + '-details-' + idx;
                content.id = cid;
                trigger.setAttribute('aria-controls', cid);
            }
        });

        function activate(index) {
            panels.forEach((p, i) => {
                const active = i === index;
                p.classList.toggle('active', active);
                if (triggers[i]) triggers[i].setAttribute('aria-expanded', active ? 'true' : 'false');
            });
        }

        panels.forEach((panel, idx) => {
            const trigger = triggers[idx];
            if (!trigger) return;
            trigger.addEventListener('click', () => activate(idx));
            trigger.addEventListener('keydown', (e) => {
                let next = -1;
                if (e.key === 'ArrowRight' || e.key === 'ArrowDown') next = (idx + 1) % panels.length;
                else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') next = (idx - 1 + panels.length) % panels.length;
                else if (e.key === 'Home') next = 0;
                else if (e.key === 'End') next = panels.length - 1;
                if (next !== -1) {
                    e.preventDefault();
                    activate(next);
                    if (triggers[next]) triggers[next].focus();
                }
            });
        });
    }

    function initAll() {
        document.querySelectorAll('.sl-feature-panels').forEach(initPanels);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }
})();
